mapper.select:
SELECT target_category AS targetCategory,
       target_id AS targetId,
       binding_key AS bindingKey,
       formula_id AS formulaId,
       override_params::text AS overrideParamsJson
FROM public.formula_bindings
WHERE game_id = #{gameId}
  AND target_category = #{targetCategory}
  AND target_id = #{targetId}
  AND binding_key = #{bindingKey}

mapper.update:
UPDATE public.formula_bindings
SET start_version_id = #{versionId},
    end_version_id = #{versionId}
WHERE game_id = #{gameId}
  AND target_category = #{targetCategory}
  AND target_id = #{targetId}
  AND binding_key = #{bindingKey}
